WITH unpacked AS (SELECT id, host, latency_ms, context['version'] AS version, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs WHERE host = 'h3') SELECT host, CASE WHEN latency_ms >= 2546 THEN 'LARGE' ELSE 'SMALL' END AS latency_ms_tier, SUM(CASE WHEN host = 'h1' THEN latency_ms ELSE 0 END) AS h1_latency_ms, MIN(latency_ms) AS min_latency_ms, SORT_ARRAY(COLLECT_SET(host)) AS host_list, GROUPING(host) AS gid FROM unpacked GROUP BY CUBE (host, CASE WHEN latency_ms >= 2546 THEN 'LARGE' ELSE 'SMALL' END)
